import {el} from '/shared/client.js';
// Crossway's nine pages, as views of one controller. The shared Web Host serves
// only gui/index.html and this file, so views, styles and icons live here.
// Every value shown comes from a Crossway tool call over the Host's fixed Agent
// MCP connection; the page keeps no business data between renders and applies
// no business rule. Choices the tools leave to the caller (which notices to
// preselect for payment, which card to offer first) use fields the tools
// return, such as a notice's `payable` flag.

