const P = 'crossway.';
const VIEWS = [
  {id: 'account', label: 'Account overview', title: 'Account overview'},
  {id: 'topup', label: 'Top up', title: 'Top up the balance'},
  {id: 'statements', label: 'Statements', title: 'Monthly statements'},
  {id: 'vehicles', label: 'Vehicles and transponders', title: 'Vehicles and transponders'},
  {id: 'tolls', label: 'Toll activity', title: 'Toll activity'},
  {id: 'notices', label: 'Notices', title: 'Violation notices'},
  {id: 'pay', label: 'Pay notices', title: 'Pay violation notices'},
  {id: 'disputes', label: 'Disputes', title: 'Disputes'},
  {id: 'policies', label: 'Policies', title: 'Rates and policies'},
];
// Tools each page calls, so the page can say which ones the current profile lacks.
const TOOLS = {
  account: ['crossway.account.get', 'crossway.account.replenish.set'],
  topup: ['crossway.account.get', 'crossway.account.topup.preview', 'crossway.account.topup.confirm'],
  statements: ['crossway.account.statements'],
  vehicles: ['crossway.vehicles.list', 'crossway.transponders.list', 'crossway.policies.get', 'crossway.vehicles.add',
    'crossway.vehicles.update', 'crossway.vehicles.end', 'crossway.transponders.assign'],
  tolls: ['crossway.tolls.list', 'crossway.policies.get'],
  notices: ['crossway.notices.list', 'crossway.notices.get'],
  pay: ['crossway.notices.list', 'crossway.account.get', 'crossway.notices.pay.preview', 'crossway.notices.pay.confirm'],
  disputes: ['crossway.disputes.reasons', 'crossway.notices.list', 'crossway.disputes.get', 'crossway.policies.get',
    'crossway.transponders.list', 'crossway.disputes.preview', 'crossway.disputes.confirm', 'crossway.disputes.withdraw'],
  policies: ['crossway.policies.get'],
};

